332:    pub fn handle_key(&mut self, key: UiKey) -> Vec<UiAction> {
333:        let command_mode_text_key = self.command_mode_text_key_control_status(key);
334:        let actions = self.handle_key_inner(key);
335:        self.update_command_mode_typing_notice(command_mode_text_key);
