584:    fn left_widget(&self) -> List<'static> {
585:        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
586:        let mut items = vec![ListItem::new(if self.control_selected == 0 {
587:            Spans::from(vec![Span::raw("> work-leaf  command")])
588:        } else {
589:            Spans::from(vec![Span::raw("  work-leaf  command")])
590:        })];
591:        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
592:            let agent = &self.agents[*agent_index];
593:            let selected = self.control_selected == visible_position + 1;
594:            let item = ListItem::new(Spans::from(vec![Span::raw(compact_agent_row(
595:                agent,
596:                selected,
597:                inner_width,
598:            ))]));
599:            let item = if agent.ready {
600:                item.style(Style::default().add_modifier(Modifier::REVERSED))
601:            } else {
602:                item
603:            };
604:            items.push(item);
605:            if !agent.modified_files.is_empty() {
606:                items.push(ListItem::new(Spans::from(vec![Span::raw(format!(
607:                    "    files: {}",
608:                    agent
609:                        .modified_files
610:                        .iter()
611:                        .map(|path| path.display().to_string())
612:                        .collect::<Vec<_>>()
613:                        .join(", ")
614:                ))])));
615:            }
616:            for (label, agents) in [
617:                ("conflicts", &agent.conflicting_agents),
618:                ("depends-on", &agent.depends_on),
619:                ("depended-on-by", &agent.depended_on_by),
620:            ] {
621:                if !agents.is_empty() {
622:                    items.push(ListItem::new(Spans::from(vec![Span::raw(format!(
623:                        "    {label}: {}",
624:                        agents
625:                            .iter()
626:                            .map(AgentId::as_str)
627:                            .collect::<Vec<_>>()
628:                            .join(", ")
629:                    ))])));
630:                }
631:            }
632:        }
633:        List::new(items).block(Block::default().title("work-leaf").borders(Borders::ALL))
634:    }
