656:    }
657:
658:    fn cursor_sequence_with_cursors(
659:        &self,
660:        right_content: &str,
661:        prompt: &str,
662:        prompt_cursor: usize,
663:        right_cursor_column: Option<usize>,
664:    ) -> String {
665:        let (row, column) = if self.mode == UiMode::Prompt {
666:            (
667:                self.height,
668:                self.prompt_view(prompt, prompt_cursor).cursor_column,
669:            )
670:        } else {
671:            match self.focus {
672:                PaneFocus::Left => (self.control_cursor_row(), 2),
673:                PaneFocus::Right => {
674:                    self.right_cursor_position_with_cursor(right_content, right_cursor_column)
675:                }
676:            }
677:        };
678:        let row = row.clamp(1, self.height.max(1));
679:        let column = column.clamp(1, self.width.max(1));
680:        format!("\u{1b}[{row};{column}H")
681:    }
682:
683:    fn prompt_view(&self, prompt: &str, prompt_cursor: usize) -> PromptView {
684:        let width = usize::from(self.width.max(1));
685:        let input_width = width.saturating_sub(1);
686:        let max_cursor_offset = width.saturating_sub(2);
687:        let cursor_chars = cursor_char_count(prompt, prompt_cursor);
688:        let start = cursor_chars.saturating_sub(max_cursor_offset);
689:        let visible_prompt = prompt
690:            .chars()
691:            .skip(start)
692:            .take(input_width)
693:            .collect::<String>();
694:        let cursor_offset = cursor_chars.saturating_sub(start).min(max_cursor_offset);
695:        let cursor_column = if self.width <= 1 {
696:            1
697:        } else {
698:            cursor_offset.saturating_add(2).min(width) as u16
699:        };
700:        PromptView {
701:            line: format!(":{visible_prompt}"),
702:            cursor_column,
703:        }
704:    }
