714:    fn handle_pending_key(&mut self, pending: PendingKey, key: UiKey) -> Vec<UiAction> {
715:        match (pending, key) {
716:            (PendingKey::CtrlW, UiKey::Char('h')) if self.mode == UiMode::Command => {
717:                if self.left_visible {
718:                    self.focus = PaneFocus::Left;
719:                }
720:                Vec::new()
721:            }
722:            (PendingKey::CtrlW, UiKey::Char('k')) if self.mode == UiMode::Command => {
723:                if self.left_visible {
724:                    self.focus = PaneFocus::Left;
725:                }
726:                Vec::new()
727:            }
