1021:    fn right_cursor_position_with_cursor(
1022:        &self,
1023:        right_content: &str,
1024:        cursor_column: Option<usize>,
1025:    ) -> (u16, u16) {
1026:        let layout = self.layout();
1027:        let inner_width = layout.right_width.saturating_sub(2).max(1);
1028:        let lines = right_content.lines().collect::<Vec<_>>();
1029:        let Some(line) = lines.last().copied() else {
1030:            return (2, layout.left_width.saturating_add(2));
1031:        };
1032:        if !line.starts_with("chat> ") {
1033:            return (2, layout.left_width.saturating_add(2));
1034:        }
1035:        let previous_rows = lines[..lines.len() - 1]
1036:            .iter()
1037:            .map(|line| visual_rows(line, inner_width))
1038:            .sum::<u16>();
1039:        let line_chars = line.chars().count();
1040:        let line_len = cursor_column
1041:            .unwrap_or(line_chars)
1042:            .min(line_chars)
1043:            .min(usize::from(u16::MAX)) as u16;
1044:        let row = 2_u16
1045:            .saturating_add(previous_rows)
1046:            .saturating_add(line_len / inner_width);
1047:        let column = layout
1048:            .left_width
1049:            .saturating_add(2)
1050:            .saturating_add(line_len % inner_width);
1051:        (row, column)
1052:    }
