1135:fn compact_agent_row(agent: &AgentListEntry, selected: bool, width: usize) -> String {
1136:    let prefix = if selected { ">" } else { " " };
1137:    let status = if agent.ready { " READY" } else { "" };
1138:    let id = agent.id.as_str();
1139:    let width = width.max(1);
1140:
