1148:
1149:fn compact_fixed_first(
1150:    prefix: &str,
1151:    fixed: &str,
1152:    flexible: &str,
1153:    status: &str,
1154:    width: usize,
1155:) -> String {
1156:    let fixed_width = prefix.chars().count() + fixed.chars().count() + status.chars().count();
1157:    if fixed_width >= width {
1158:        return format!("{prefix}{fixed}{status}");
1159:    }
1160:
1161:    let flexible_width = width.saturating_sub(fixed_width + 1);
1162:    format!(
1163:        "{prefix}{fixed} {}{status}",
1164:        truncate_to_width(flexible, flexible_width)
1165:    )
1166:}
1167:
1168:fn compact_fixed_last(
1169:    prefix: &str,
1170:    flexible: &str,
1171:    fixed: &str,
1172:    status: &str,
1173:    width: usize,
1174:) -> String {
1175:    let fixed_width = prefix.chars().count() + 1 + fixed.chars().count() + status.chars().count();
1176:    if fixed_width >= width {
1177:        return format!("{prefix}{fixed}{status}");
1178:    }
1179:
1180:    let flexible_width = width.saturating_sub(fixed_width);
1181:    format!(
1182:        "{prefix}{} {fixed}{status}",
1183:        truncate_to_width(flexible, flexible_width)
1184:    )
1185:}
